import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Set;
import java.util.concurrent.Callable;
import java.util.concurrent.ExecutionException;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.Future;

public class CosmicCats {
    private final Set<String> identifiers;

    public CosmicCats() {
        Set<String> mutable = new LinkedHashSet<String>();
        mutable.add("Whiskers");
        mutable.add("Paws");
        mutable.add("Claw");
        this.identifiers = Collections.unmodifiableSet(new LinkedHashSet<String>(mutable));
    }

    public boolean isCat(String identifier) {
        return identifiers.contains(identifier);
    }

    public String displayCats() {
        return new ArrayList<String>(identifiers).toString();
    }

    public static void main(String[] args) {
        final CosmicCats cats = new CosmicCats();
        ExecutorService executor = Executors.newFixedThreadPool(2);

        Callable<String> displayTask = new Callable<String>() {
            @Override
            public String call() {
                return cats.displayCats();
            }
        };

        Callable<List<String>> checkTask = new Callable<List<String>>() {
            @Override
            public List<String> call() {
                List<String> checks = Arrays.asList("Whiskers", "Nova", "Paws", "Claw", "Shadow");
                List<String> results = new ArrayList<String>();
                for (String value : checks) {
                    results.add(value + "=" + cats.isCat(value));
                }
                return results;
            }
        };

        Future<String> displayFuture = executor.submit(displayTask);
        Future<List<String>> checkFuture = executor.submit(checkTask);

        try {
            String display = displayFuture.get();
            List<String> results = checkFuture.get();
            System.out.println(display);
            for (String result : results) {
                System.out.println(result);
            }
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
            System.out.println("Interrupted");
        } catch (ExecutionException e) {
            System.out.println("Execution failed");
        } finally {
            executor.shutdown();
        }
    }
}
```

