import java.util.Collections;
import java.util.HashMap;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;

public class DelegatingDeviceTracker {
    private final ConcurrentHashMap<String, Position> locations;
    private final Map<String, Position> unmodifiableLiveView;

    public DelegatingDeviceTracker(Map<String, Position> initialLocations) {
        this.locations = new ConcurrentHashMap<String, Position>(initialLocations);
        this.unmodifiableLiveView = Collections.unmodifiableMap(this.locations);
    }

    public Position getPosition(String gadgetId) {
        return locations.get(gadgetId);
    }

    public boolean updatePosition(String gadgetId, int x, int y) {
        return locations.replace(gadgetId, new Position(x, y)) != null;
    }

    public Map<String, Position> getAllPositionsLive() {
        return unmodifiableLiveView;
    }

    public Map<String, Position> getAllPositionsSnapshot() {
        return Collections.unmodifiableMap(new HashMap<String, Position>(locations));
    }

    public static void main(String[] args) {
        Map<String, Position> initial = new HashMap<String, Position>();
        initial.put("gadget-1", new Position(0, 0));
        initial.put("gadget-2", new Position(10, 10));
        initial.put("gadget-3", new Position(20, 20));

        final DelegatingDeviceTracker tracker = new DelegatingDeviceTracker(initial);

        ExecutorService executor = Executors.newFixedThreadPool(2);

        Runnable updaterTask = new Runnable() {
            @Override
            public void run() {
                boolean updated1 = tracker.updatePosition("gadget-1", 5, 5);
                boolean updated2 = tracker.updatePosition("gadget-2", 15, 15);
                boolean updatedMissing = tracker.updatePosition("gadget-99", 99, 99);

                System.out.println(Thread.currentThread().getName() + " updated gadget-1: " + updated1);
                System.out.println(Thread.currentThread().getName() + " updated gadget-2: " + updated2);
                System.out.println(Thread.currentThread().getName() + " updated gadget-99: " + updatedMissing);
            }
        };

        Runnable readerTask = new Runnable() {
            @Override
            public void run() {
                System.out.println(Thread.currentThread().getName() + " live view: " + tracker.getAllPositionsLive());
                System.out.println(Thread.currentThread().getName() + " snapshot: " + tracker.getAllPositionsSnapshot());
                System.out.println(Thread.currentThread().getName() + " position of gadget-1: " + tracker.getPosition("gadget-1"));
            }
        };

        executor.submit(updaterTask);
        executor.submit(readerTask);

        executor.shutdown();
        try {
            if (!executor.awaitTermination(5, TimeUnit.SECONDS)) {
                executor.shutdownNow();
            }
        } catch (InterruptedException e) {
            executor.shutdownNow();
            Thread.currentThread().interrupt();
        }

        System.out.println("Final live view from main: " + tracker.getAllPositionsLive());
        System.out.println("Final snapshot from main: " + tracker.getAllPositionsSnapshot());
    }
}

class Position {
    private final int x;
    private final int y;

    public Position(int x, int y) {
        this.x = x;
        this.y = y;
    }

    public int getX() {
        return x;
    }

    public int getY() {
        return y;
    }

    public String toString() {
        return "(" + x + ", " + y + ")";
    }
}
```

