import java.util.Collections;
import java.util.HashMap;
import java.util.Map;
import java.util.Objects;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.ConcurrentMap;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;

public class DelegatingParcelTracker {

    private final ConcurrentMap<String, Position> locations;
    private final Map<String, Position> unmodifiableLiveView;

    public DelegatingParcelTracker(Map<String, Position> initialPositions) {
        if (initialPositions == null) {
            throw new IllegalArgumentException("initialPositions must not be null");
        }

        this.locations = new ConcurrentHashMap<>();
        for (Map.Entry<String, Position> entry : initialPositions.entrySet()) {
            String id = Objects.requireNonNull(entry.getKey(), "package ID must not be null");
            Position pos = Objects.requireNonNull(entry.getValue(), "position must not be null");
            this.locations.put(id, pos);
        }

        this.unmodifiableLiveView = Collections.unmodifiableMap(this.locations);
    }

    public Position getPosition(String packageId) {
        Objects.requireNonNull(packageId, "packageId must not be null");
        return locations.get(packageId);
    }

    public boolean setPosition(String packageId, int x, int y) {
        Objects.requireNonNull(packageId, "packageId must not be null");
        return locations.replace(packageId, new Position(x, y)) != null;
    }

    public Map<String, Position> getAllPositionsLive() {
        return unmodifiableLiveView;
    }

    public Map<String, Position> getAllPositionsSnapshot() {
        return Collections.unmodifiableMap(new HashMap<>(locations));
    }

    public static void main(String[] args) {
        Map<String, Position> initial = new HashMap<>();
        initial.put("PKG-100", new Position(0, 0));
        initial.put("PKG-200", new Position(10, 10));
        initial.put("PKG-300", new Position(20, 20));

        DelegatingParcelTracker tracker = new DelegatingParcelTracker(initial);

        System.out.println("Initial live view: " + tracker.getAllPositionsLive());
        System.out.println("Initial snapshot : " + tracker.getAllPositionsSnapshot());

        ExecutorService executor = Executors.newFixedThreadPool(2);

        Runnable updater1 = new Runnable() {
            @Override
            public void run() {
                boolean updated1 = tracker.setPosition("PKG-100", 5, 7);
                boolean updated2 = tracker.setPosition("PKG-999", 50, 50); // should fail
                System.out.println(Thread.currentThread().getName()
                        + " updated PKG-100: " + updated1);
                System.out.println(Thread.currentThread().getName()
                        + " updated PKG-999: " + updated2);
            }
        };

        Runnable updater2 = new Runnable() {
            @Override
            public void run() {
                boolean updated1 = tracker.setPosition("PKG-200", 15, 18);
                boolean updated2 = tracker.setPosition("PKG-300", 25, 30);
                System.out.println(Thread.currentThread().getName()
                        + " updated PKG-200: " + updated1);
                System.out.println(Thread.currentThread().getName()
                        + " updated PKG-300: " + updated2);
            }
        };

        executor.submit(updater1);
        executor.submit(updater2);

        executor.shutdown();
        try {
            if (!executor.awaitTermination(5, TimeUnit.SECONDS)) {
                executor.shutdownNow();
            }
        } catch (InterruptedException e) {
            executor.shutdownNow();
            Thread.currentThread().interrupt();
        }

        System.out.println("Position of PKG-100: " + tracker.getPosition("PKG-100"));
        System.out.println("Position of PKG-200: " + tracker.getPosition("PKG-200"));
        System.out.println("Final live view    : " + tracker.getAllPositionsLive());
        System.out.println("Final snapshot     : " + tracker.getAllPositionsSnapshot());
    }
}

final class Position {
    private final int x;
    private final int y;

    public Position(int x, int y) {
        this.x = x;
        this.y = y;
    }

    public int getX() {
        return x;
    }

    public int getY() {
        return y;
    }

    @Override
    public String toString() {
        return "(" + x + ", " + y + ")";
    }
}
