    public DelegatingRobotTracker(Map<String, Point> initialLocations) {
        if (initialLocations == null) {
            throw new NullPointerException("initialLocations must not be null");
        }
        this.robotLocations = new ConcurrentHashMap<>(initialLocations);
        this.liveView = Collections.unmodifiableMap(robotLocations);
    }

    public Point getLocation(String robotId) {
        if (robotId == null) {
            throw new NullPointerException("robotId must not be null");
        }
        return robotLocations.get(robotId);
    }

    public boolean setLocation(String robotId, int x, int y) {
        if (robotId == null) {
            throw new NullPointerException("robotId must not be null");
        }
        return robotLocations.replace(robotId, new Point(x, y)) != null;
    }

    public Map<String, Point> getLocations() {
        return liveView;
    }

    public Map<String, Point> getLocationsSnapshot() {
        return Collections.unmodifiableMap(new HashMap<>(robotLocations));
    }

    public static void main(String[] args) {
        Map<String, Point> initial = new HashMap<>();
        initial.put("R1", new Point(0, 0));
        initial.put("R2", new Point(10, 10));
        initial.put("R3", new Point(20, 20));

        final DelegatingRobotTracker tracker = new DelegatingRobotTracker(initial);

        ExecutorService executor = Executors.newFixedThreadPool(2);

        Runnable updaterTask = new Runnable() {
            @Override
            public void run() {
                tracker.setLocation("R1", 1, 1);
                tracker.setLocation("R2", 11, 11);
                tracker.setLocation("R4", 100, 100); // will fail because R4 does not exist

                System.out.println(Thread.currentThread().getName() + " updated locations.");
            }
        };

        Runnable readerTask = new Runnable() {
            @Override
            public void run() {
                System.out.println(Thread.currentThread().getName() + " live view: " + tracker.getLocations());
                System.out.println(Thread.currentThread().getName() + " snapshot: " + tracker.getLocationsSnapshot());
                System.out.println(Thread.currentThread().getName() + " location of R1: " + tracker.getLocation("R1"));
            }
        };

        executor.submit(updaterTask);
        executor.submit(readerTask);

        executor.shutdown();
        try {
            if (!executor.awaitTermination(5, TimeUnit.SECONDS)) {
                executor.shutdownNow();
            }
        } catch (InterruptedException e) {
            executor.shutdownNow();
            Thread.currentThread().interrupt();
        }

        System.out.println("Final live view: " + tracker.getLocations());
        System.out.println("Final snapshot: " + tracker.getLocationsSnapshot());
    }
}

