import java.util.Random;
import java.util.concurrent.Callable;
import java.util.concurrent.ExecutionException;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.Future;
import java.util.concurrent.ThreadLocalRandom;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.TimeoutException;
import java.util.concurrent.locks.ReentrantLock;

public class ParcelLockerApp {

    public static final class NotEnoughItemsException extends Exception {
        public NotEnoughItemsException(String message) {
            super(message);
        }
    }

    public static final class ParcelCount {
        private int count;

        public ParcelCount(int initialCount) {
            this.count = initialCount;
        }

        public int get() {
            return count;
        }

        public void add(int quantity) {
            count += quantity;
        }

        public void subtract(int quantity) {
            count -= quantity;
        }
    }

    public static final class Locker {
        private final String name;
        private final ReentrantLock lock;
        private final ParcelCount parcelCount;

        public Locker(String name, int initialItems) {
            this.name = name;
            this.lock = new ReentrantLock();
            this.parcelCount = new ParcelCount(initialItems);
        }

        public String getName() {
            return name;
        }

        public ReentrantLock getLock() {
            return lock;
        }

        public int getItemCount() {
            return parcelCount.get();
        }

        private void withdraw(int quantity) {
            parcelCount.subtract(quantity);
        }

        private void deposit(int quantity) {
            parcelCount.add(quantity);
        }

        @Override
        public String toString() {
            return "Locker{name='" + name + "', items=" + getItemCount() + "}";
        }
    }

    public static boolean move(Locker source,
                               Locker target,
                               int quantity,
                               long timeout,
                               TimeUnit unit) throws InterruptedException, NotEnoughItemsException {
        if (source == null || target == null) {
            throw new IllegalArgumentException("Lockers must not be null");
        }
        if (source == target) {
            return true;
        }
        if (quantity < 0) {
            throw new IllegalArgumentException("Quantity must not be negative");
        }
        if (quantity == 0) {
            return true;
        }

        final long timeoutNanos = unit.toNanos(timeout);
        final long deadline = System.nanoTime() + timeoutNanos;
        final Random random = ThreadLocalRandom.current();

        while (true) {
            long remaining = deadline - System.nanoTime();
            if (remaining <= 0L) {
                return false;
            }

            if (source.getLock().tryLock(remaining, TimeUnit.NANOSECONDS)) {
                try {
                    remaining = deadline - System.nanoTime();
                    if (remaining <= 0L) {
                        return false;
                    }

                    if (target.getLock().tryLock(remaining, TimeUnit.NANOSECONDS)) {
                        try {
                            if (source.getItemCount() < quantity) {
                                throw new NotEnoughItemsException(
                                        "Not enough items in locker " + source.getName() + " to move " + quantity
                                );
                            }
                            source.withdraw(quantity);
                            target.deposit(quantity);
                            return true;
                        } finally {
                            target.getLock().unlock();
                        }
                    }
                } finally {
                    source.getLock().unlock();
                }
            }

            long delay = fixedDelayComponentNanos(timeoutNanos) + randomDelayComponentNanos(random, timeoutNanos);
            remaining = deadline - System.nanoTime();
            if (remaining <= 0L) {
                return false;
            }
            if (delay > remaining) {
                delay = remaining;
            }
            if (delay > 0L) {
                TimeUnit.NANOSECONDS.sleep(delay);
            }
        }
    }

    private static long fixedDelayComponentNanos(long timeoutNanos) {
        long base = timeoutNanos / 20L;
        long min = TimeUnit.MILLISECONDS.toNanos(1L);
        long max = TimeUnit.MILLISECONDS.toNanos(50L);
        if (base < min) {
            return min;
        }
        return Math.min(base, max);
    }

    private static long randomDelayComponentNanos(Random random, long timeoutNanos) {
        long bound = timeoutNanos / 10L;
        long min = TimeUnit.MILLISECONDS.toNanos(1L);
        long max = TimeUnit.MILLISECONDS.toNanos(25L);
        if (bound < min) {
            bound = min;
        }
        bound = Math.min(bound, max);
        if (bound <= 1L) {
            return 0L;
        }
        long value = Math.abs(random.nextLong());
        return value % bound;
    }

    public static void main(String[] args) {
        final Locker lockerA = new Locker("A", 100);
        final Locker lockerB = new Locker("B", 50);

        ExecutorService executor = Executors.newFixedThreadPool(2);

        Callable<String> task1 = new Callable<String>() {
            @Override
            public String call() {
                try {
                    boolean moved = move(lockerA, lockerB, 30, 2, TimeUnit.SECONDS);
                    return "Task1 moved=" + moved + " " + lockerA + " " + lockerB;
                } catch (InterruptedException e) {
                    Thread.currentThread().interrupt();
                    return "Task1 interrupted";
                } catch (NotEnoughItemsException e) {
                    return "Task1 failed: " + e.getMessage();
                }
            }
        };

        Callable<String> task2 = new Callable<String>() {
            @Override
            public String call() {
                try {
                    boolean moved = move(lockerB, lockerA, 20, 2, TimeUnit.SECONDS);
                    return "Task2 moved=" + moved + " " + lockerA + " " + lockerB;
                } catch (InterruptedException e) {
                    Thread.currentThread().interrupt();
                    return "Task2 interrupted";
                } catch (NotEnoughItemsException e) {
                    return "Task2 failed: " + e.getMessage();
                }
            }
        };

        Future<String> result1 = executor.submit(task1);
        Future<String> result2 = executor.submit(task2);

        try {
            System.out.println(result1.get());
            System.out.println(result2.get());
            System.out.println("Final state: " + lockerA + " " + lockerB);
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
            System.out.println("Main interrupted");
        } catch (ExecutionException e) {
            Throwable cause = e.getCause();
            if (cause != null) {
                System.out.println("Execution failed: " + cause.getMessage());
            } else {
                System.out.println("Execution failed");
            }
        } finally {
            executor.shutdown();
            try {
                if (!executor.awaitTermination(5, TimeUnit.SECONDS)) {
                    executor.shutdownNow();
                }
            } catch (InterruptedException e) {
                executor.shutdownNow();
                Thread.currentThread().interrupt();
            }
        }
    }
}
