public class DeadlockAvoidanceSwapProgram {

    public static void main(String[] args) throws Exception {
        final Container containerA = new Container("A", 100);
        final Container containerB = new Container("B", 50);

        ExecutorService executor = Executors.newFixedThreadPool(2);

        Callable<String> task1 = new Callable<String>() {
            @Override
            public String call() {
