        }

        executor.shutdown();
        executor.awaitTermination(5, TimeUnit.SECONDS);

        System.out.println("Final state: " + containerA + " " + containerB);
    }

    public static boolean swap(Container origin,
                               Container target,
                               int elementsToSwap,
                               long timeout,
                               TimeUnit unit)
            throws InterruptedException, InsufficientElementsException {

        if (origin == null || target == null) {
            throw new IllegalArgumentException("Containers must not be null");
        }
        if (origin == target) {
            throw new IllegalArgumentException("Origin and target must be different containers");
        }
        if (elementsToSwap < 0) {
            throw new IllegalArgumentException("elementsToSwap must be non-negative");
        }
        if (timeout < 0) {
            throw new IllegalArgumentException("timeout must be non-negative");
        }

        final long deadline = System.nanoTime() + unit.toNanos(timeout);
        final Random random = ThreadLocalRandom.current();

        while (true) {
            long remainingNanos = deadline - System.nanoTime();
            if (remainingNanos <= 0L) {
                return false;
            }

            if (origin.getLock().tryLock(remainingNanos, TimeUnit.NANOSECONDS)) {
