                    boolean moved = move(binA, binB, 30, 2, TimeUnit.SECONDS);
                    return Thread.currentThread().getName() + " move A->B 30 result=" + moved;
                } catch (NotEnoughWidgetsException e) {
                    return Thread.currentThread().getName() + " move A->B failed: " + e.getMessage();
                } catch (InterruptedException e) {
                    Thread.currentThread().interrupt();
                    return Thread.currentThread().getName() + " interrupted";
                }
            }
        });

        tasks.add(new Callable<String>() {
            @Override
            public String call() {
                try {
                    boolean moved = move(binB, binA, 40, 2, TimeUnit.SECONDS);
                    return Thread.currentThread().getName() + " move B->A 40 result=" + moved;
                } catch (NotEnoughWidgetsException e) {
                    return Thread.currentThread().getName() + " move B->A failed: " + e.getMessage();
                } catch (InterruptedException e) {
                    Thread.currentThread().interrupt();
                    return Thread.currentThread().getName() + " interrupted";
                }
            }
        });

        List<Future<String>> results = executor.invokeAll(tasks);
        executor.shutdown();
        executor.awaitTermination(5, TimeUnit.SECONDS);

        for (Future<String> future : results) {
            try {
                System.out.println(future.get());
            } catch (TimeoutException e) {
                System.out.println("Timed out waiting for task result");
            }
        }

        System.out.println(binA);
        System.out.println(binB);
        System.out.println(binC);
    }

    public static boolean move(Bin source, Bin target, int widgetCount, long timeout, TimeUnit unit)
            throws InterruptedException, NotEnoughWidgetsException {
        if (source == null || target == null) {
            throw new IllegalArgumentException("Bins must not be null");
        }
        if (source == target) {
            return true;
        }
        if (widgetCount < 0) {
            throw new IllegalArgumentException("widgetCount must not be negative");
        }

        long timeoutNanos = unit.toNanos(timeout);
        long deadline = System.nanoTime() + timeoutNanos;
        long fixedDelay = getFixedDelayComponentNanos(timeoutNanos);
        long randomDelayBound = getRandomDelayComponentNanos(timeoutNanos);

        for (;;) {
            if (Thread.interrupted()) {
                throw new InterruptedException();
            }

            if (tryAcquireBothLocks(source, target)) {
                try {
                    if (source.getWidgetCount() < widgetCount) {
                        throw new NotEnoughWidgetsException("Source bin " + source.getName()
                                + " does not contain enough widgets: requested=" + widgetCount
                                + ", available=" + source.getWidgetCount());
                    }
                    source.removeWidgets(widgetCount);
                    target.addWidgets(widgetCount);
                    return true;
                } finally {
                    target.unlock();
                    source.unlock();
                }
            }

            long remaining = deadline - System.nanoTime();
            if (remaining <= 0L) {
                return false;
            }

            long pause = fixedDelay + randomDelay(randomDelayBound);
            if (pause > remaining) {
                pause = remaining;
            }
            if (pause > 0L) {
                TimeUnit.NANOSECONDS.sleep(pause);
            }
        }
    }

    private static boolean tryAcquireBothLocks(Bin source, Bin target) throws InterruptedException {
        if (!source.tryLock(0, TimeUnit.NANOSECONDS)) {
            return false;
        }
        boolean targetLocked = false;
        try {
            targetLocked = target.tryLock(0, TimeUnit.NANOSECONDS);
            if (!targetLocked) {
                return false;
            }
            return true;
        } finally {
            if (!targetLocked) {
                source.unlock();
            }
        }
    }

    private static long getFixedDelayComponentNanos(long timeoutNanos) {
        long base = timeoutNanos / 20L;
        return Math.max(TimeUnit.MILLISECONDS.toNanos(1), base);
    }

    private static long getRandomDelayComponentNanos(long timeoutNanos) {
        long base = timeoutNanos / 10L;
        return Math.max(TimeUnit.MILLISECONDS.toNanos(1), base);
    }

    private static long randomDelay(long boundNanos) {
        if (boundNanos <= 1L) {
            return 0L;
        }
        long value = Math.abs(RANDOM.nextLong());
        return value % boundNanos;
    }

    public static final class WidgetCount {
        private int count;

