                if (bucketsA != null) {
                    solarRunes.addAll(bucketsA.getSolarRunes());
                    lunarRunes.addAll(bucketsA.getLunarRunes());
                }
                if (bucketsB != null) {
                    solarRunes.addAll(bucketsB.getSolarRunes());
                    lunarRunes.addAll(bucketsB.getLunarRunes());
                }

                int pairCount = Math.min(solarRunes.size(), lunarRunes.size());
                for (int i = 0; i < pairCount; i++) {
                    Rune left = solarRunes.get(i);
                    Rune right = lunarRunes.get(i);
                    if (left.getConstellation() == right.getConstellation()
                            && left.getResonance().isOpposite(right.getResonance())) {
