    }
}

final class Harmony {
    private final Rune first;
    private final Rune second;

    public Harmony(Rune first, Rune second) {
        if (first == null || second == null) {
            throw new IllegalArgumentException("Runes must not be null");
        }
        if (first.getConstellation() != second.getConstellation()) {
            throw new IllegalArgumentException("Runes must share the same constellation");
        }
        if (!first.getResonance().isOpposite(second.getResonance())) {
            throw new IllegalArgumentException("Runes must have opposite resonances");
        }
        this.first = first;
        this.second = second;
    }

    public Rune getFirst() {
        return first;
