}

final class ResonanceBuckets {
    private final List<Rune> solarRunes = new ArrayList<Rune>();
    private final List<Rune> lunarRunes = new ArrayList<Rune>();

    public void add(Rune rune) {
        if (rune.getResonance() == Resonance.SOLAR) {
            solarRunes.add(rune);
        } else {
            lunarRunes.add(rune);
        }
    }

    public List<Rune> getSolarRunes() {
        return solarRunes;
    }

    public List<Rune> getLunarRunes() {
        return lunarRunes;
    }
}

final class RunePartitionTask implements Callable<Map<Constellation, ResonanceBuckets>> {
    private final List<Rune> runes;

    public RunePartitionTask(List<Rune> runes) {
        this.runes = new ArrayList<Rune>(runes);
    }

    @Override
    public Map<Constellation, ResonanceBuckets> call() {
        Map<Constellation, ResonanceBuckets> grouped = new EnumMap<Constellation, ResonanceBuckets>(Constellation.class);
        for (Rune rune : runes) {
            ResonanceBuckets buckets = grouped.get(rune.getConstellation());
            if (buckets == null) {
                buckets = new ResonanceBuckets();
                grouped.put(rune.getConstellation(), buckets);
            }
            buckets.add(rune);
        }
        return grouped;
    }
}
