        initial.put("quasar", new Starlight(3, 30));
        initial.put("comet", new Starlight(4, 40));

        final CelestialCaravanTracker tracker = new CelestialCaravanTracker(initial);

        ExecutorService executor = Executors.newFixedThreadPool(4);

        Runnable mover1 = new Runnable() {
            public void run() {
                for (int i = 0; i < 5; i++) {
                    tracker.setHaven("aurora", 100 + i, 200 + i);
                    sleepQuietly(20);
