        Runnable mover2 = new Runnable() {
            public void run() {
                for (int i = 0; i < 5; i++) {
                    tracker.setHaven("nebula", 300 + i, 400 + i);
                    sleepQuietly(25);
                }
            }
        };

        Runnable reader = new Runnable() {
            public void run() {
                for (int i = 0; i < 5; i++) {
                    Map<String, Starlight> snapshot = tracker.getHavensAsStatic();
                    snapshot.size();
                    tracker.getHaven("quasar");
                    sleepQuietly(15);
                }
            }
        };

        Runnable mover3 = new Runnable() {
            public void run() {
                for (int i = 0; i < 5; i++) {
                    tracker.setHaven("comet", 500 + i, 600 + i);
                    sleepQuietly(10);
                }
            }
        };

        executor.submit(mover1);
        executor.submit(mover2);
        executor.submit(reader);
        executor.submit(mover3);

        executor.shutdown();
        executor.awaitTermination(10, TimeUnit.SECONDS);

        Map<String, Starlight> finalSnapshot = tracker.getHavensAsStatic();
        for (Map.Entry<String, Starlight> entry : finalSnapshot.entrySet()) {
            System.out.println(entry.getKey() + " -> " + entry.getValue());
