        List<R> results = new CopyOnWriteArrayList<>();
        List<Future<?>> futures = new ArrayList<>();
        for (final SigilNode<? extends R> node : forest) {
            futures.add(executor.submit(new Runnable() {
                @Override
                public void run() {
                    processSigilNodeParallel(node, results, executor);
                }
            }));
        }
        waitForAll(futures);
        return new ArrayList<>(results);
    }

    private static <R> void processSigilNodeParallel(
            SigilNode<? extends R> node,
            List<R> results,
            ExecutorService executor) {
        results.add(node.compute());
        List<Future<?>> childFutures = new ArrayList<>();
        for (final SigilNode<? extends R> child : node.getChildren()) {
            childFutures.add(executor.submit(new Runnable() {
                @Override
                public void run() {
                    processSigilNodeParallel(child, results, executor);
                }
            }));
        }
        waitForAllUnchecked(childFutures);
    }

    private static void waitForAll(List<Future<?>> futures) throws Exception {
        for (Future<?> future : futures) {
            future.get();
        }
    }

    private static void waitForAllUnchecked(List<Future<?>> futures) {
        for (Future<?> future : futures) {
            try {
                future.get();
            } catch (Exception e) {
                throw new RuntimeException(e);
            }
        }
    }
