class OrbVault {
    private final Orb[] buffer;
    private int head;
    private int tail;
    private int count;
    private final Semaphore availableOrbs;
    private final Semaphore remainingSlots;
    private final Object lock = new Object();

    public OrbVault(int capacity) {
        if (capacity <= 0) {
            throw new IllegalArgumentException("Capacity must be greater than zero.");
        }
        this.buffer = new Orb[capacity];
        this.availableOrbs = new Semaphore(0);
        this.remainingSlots = new Semaphore(capacity);
    }

    public void put(Orb x) throws InterruptedException {
        if (x == null) {
            throw new IllegalArgumentException("Orb cannot be null.");
        }
        remainingSlots.acquire();
        synchronized (lock) {
            buffer[tail] = x;
            tail = (tail + 1) % buffer.length;
            count++;
        }
        availableOrbs.release();
    }

    public Orb take() throws InterruptedException {
        availableOrbs.acquire();
        Orb result;
        synchronized (lock) {
            result = buffer[head];
            buffer[head] = null;
            head = (head + 1) % buffer.length;
            count--;
        }
        remainingSlots.release();
        return result;
    }

    public boolean isEmpty() {
        synchronized (lock) {
            return count == 0;
        }
    }

    public boolean isFull() {
        synchronized (lock) {
            return count == buffer.length;
        }
    }
}

