import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;

public class SafeListener {
    private final EventListener listener;
    private int handledEvents;

    private SafeListener() {
        this.listener = new EventListener() {
            @Override
            public void onEvent(Event e) {
                SafeListener.this.doSomething(e);
            }
        };
    }

    public static SafeListener newInstance(EventSource source) {
        SafeListener safe = new SafeListener();
        source.registerListener(safe.listener);
        return safe;
    }

    private synchronized void doSomething(Event e) {
        handledEvents++;
        System.out.println("Handled event on thread: " + Thread.currentThread().getName() + ", count=" + handledEvents);
    }

    public static void main(String[] args) throws InterruptedException {
        EventSource source = new EventSource();
        SafeListener listener = SafeListener.newInstance(source);

        ExecutorService executor = Executors.newFixedThreadPool(1);
        executor.submit(new Runnable() {
            @Override
            public void run() {
                source.fireEvent(new Event());
                source.fireEvent(new Event());
                source.fireEvent(new Event());
            }
        });

        executor.shutdown();
        executor.awaitTermination(5, TimeUnit.SECONDS);

        synchronized (listener) {
            System.out.println("Final handled event count: " + listener.handledEvents);
        }
    }
}

class EventSource {
    private EventListener listener;

    public synchronized void registerListener(EventListener listener) {
        this.listener = listener;
    }

    public void fireEvent(Event event) {
        EventListener current;
        synchronized (this) {
            current = listener;
        }
        if (current != null) {
            current.onEvent(event);
        }
    }
}

interface EventListener {
    void onEvent(Event e);
}

class Event {
}
